package nl.juiced.guhs.feature.einde2.geestwezens;

import java.util.Arrays;
import java.util.List;

import nl.juiced.guhs.entity.GuhNpcEntity;

/**
 * einde2, slice geestmodellen: the table of its characters (CONTRACT_E2 11.2 H), one row per {@link GuhNpcEntity.Kind} of
 * the block {@code // <einde2_geest>}, in that order: the Theegeest of the Geestenwereld's tea pavilion (a see-through, glowing
 * spirit guh with his tea kettle) and the Bestelguh of tech tier 5 (DESIGN_EINDE2 6; his model, phase C gives him his work).
 * Both sit on the guh body ({@code zit}). Resources (generated by tools/features/einde2_geestmodellen_kinds.py, whose
 * {@code KINDS} holds the same rows and checks this file): {@code geckolib/models/entity/guh_npc_<kind>.geo.json},
 * {@code textures/entity/npc_<kind>.png} (+ {@code _glowmask}), {@code geckolib/animations/entity/guh_npc_<kind>.animation.json}.
 * The last column lists the animations besides {@code idle} with their length in ticks ({@code 0} = a pose that lasts).
 */
public enum GeestKinds {
    THEEGEEST_GUH(GuhNpcEntity.Kind.THEEGEEST_GUH, true, true, "praat:24,schenk:60,slurp:48", ""),
    BESTELGUH(GuhNpcEntity.Kind.BESTELGUH, false, false, "praat:24,bonnetje:48,ren:0", ""),
    // phase B (CONTRACT_E2_B 7.7): the echo-masters of the White Lotus, its old members, Guru Pathik and earlier Guhvatars
    // (tools/features/einde2_geestmodellen_echo.py; every one is its own character with its own animation file)
    JEONG_JEONG_GUH_ECHO(GuhNpcEntity.Kind.JEONG_JEONG_GUH_ECHO, true, true, "praat:24,kaars:40,waarschuw:30,tegel:40,verschijn:40", ""),
    OOM_MIROH_ECHO(GuhNpcEntity.Kind.OOM_MIROH_ECHO, true, true, "praat:24,thee:64,lach:36,wijsheid:44,tegel:40,verschijn:40", ""),
    BUMI_GUH_ECHO(GuhNpcEntity.Kind.BUMI_GUH_ECHO, true, true, "praat:24,giechel:30,spierbal:40,tegel:40,verschijn:40", ""),
    PAKGUH_ECHO(GuhNpcEntity.Kind.PAKGUH_ECHO, true, true, "praat:24,waterzweep:30,snor:40,tegel:40,verschijn:40", ""),
    PIANDAO_GUH_ECHO(GuhNpcEntity.Kind.PIANDAO_GUH_ECHO, true, true, "praat:24,buig:30,garde:0,pareer:10,slag:10,tegel:40,verschijn:40", ""),
    LOTUS_STICHTER_ECHO(GuhNpcEntity.Kind.LOTUS_STICHTER_ECHO, true, true, "praat:24,verhaal:60,buig:30,verschijn:40", ""),
    LOTUS_LID_ECHO(GuhNpcEntity.Kind.LOTUS_LID_ECHO, true, true, "praat:24,buig:30,knik:24,verschijn:40", "mix_0_hoed mix_0_sjerp|mix_1_haar mix_1_kraag|mix_2_haar mix_2_mantel"),
    GURU_PATHIK_GUH(GuhNpcEntity.Kind.GURU_PATHIK_GUH, true, true, "praat:24,wijs:30,sap:40,mediteer:0,verschijn:40", ""),
    KURUK_GUH(GuhNpcEntity.Kind.KURUK_GUH, true, true, "praat:24,water:40,verschijn:40,staat:0", ""),
    YANGCHEN_GUH(GuhNpcEntity.Kind.YANGCHEN_GUH, true, true, "praat:24,lucht:40,verschijn:40,staat:0", ""),
    SZETO_GUH(GuhNpcEntity.Kind.SZETO_GUH, true, true, "praat:24,vuur:40,verschijn:40,staat:0", "");

    public final GuhNpcEntity.Kind kind;
    private final boolean doorzichtig, gloed;
    private final List<String> animaties;
    private final int[] duren;
    private final List<List<String>> mixSets;

    GeestKinds(GuhNpcEntity.Kind kind, boolean doorzichtig, boolean gloed, String animaties, String mix) {
        this.kind = kind;
        this.doorzichtig = doorzichtig;
        this.gloed = gloed;
        String[] delen = animaties.split(",");
        this.animaties = Arrays.stream(delen).map(a -> a.substring(0, a.indexOf(':'))).toList();
        this.duren = Arrays.stream(delen).mapToInt(a -> Integer.parseInt(a.substring(a.indexOf(':') + 1))).toArray();
        this.mixSets = mix.isEmpty() ? List.of() : Arrays.stream(mix.split("[|]")).map(set -> List.of(set.split(" "))).toList();
    }

    /** The row of a kind (null: not one of this slice). */
    public static GeestKinds rij(GuhNpcEntity.Kind kind) {
        for (GeestKinds r : values()) {
            if (r.kind == kind) {
                return r;
            }
        }
        return null;
    }

    private static GeestKinds moet(GuhNpcEntity.Kind kind) {
        GeestKinds r = rij(kind);
        if (r == null) {
            throw new IllegalArgumentException(kind + " is not a kind of the slice geestmodellen");
        }
        return r;
    }

    /** Every kind of the slice, in the order of the Kind block. */
    public static List<GuhNpcEntity.Kind> kinds() {
        return Arrays.stream(values()).map(r -> r.kind).toList();
    }

    /** The character a look belongs to: each is its own. */
    public static GuhNpcEntity.Kind basis(GuhNpcEntity.Kind kind) {
        return moet(kind).kind;
    }

    public static String lijf(GuhNpcEntity.Kind kind) {
        moet(kind);
        return "zit";
    }

    /** How many mix sets (0: none; LOTUS_LID_ECHO: an earth, a water and a fire member). */
    public static int mix(GuhNpcEntity.Kind kind) {
        return moet(kind).mixSets.size();
    }

    /** The bones mix_&lt;i&gt;_... of set i. */
    public static List<String> mixBotten(GuhNpcEntity.Kind kind, int i) {
        List<List<String>> sets = moet(kind).mixSets;
        return i < 0 || i >= sets.size() ? List.of() : sets.get(i);
    }

    public static boolean doorzichtig(GuhNpcEntity.Kind kind) {
        return moet(kind).doorzichtig;
    }

    /** Then npc_&lt;kind&gt;_glowmask.png exists. */
    public static boolean gloed(GuhNpcEntity.Kind kind) {
        return moet(kind).gloed;
    }

    /** The names besides idle; the first is always "praat". */
    public static List<String> animaties(GuhNpcEntity.Kind kind) {
        return moet(kind).animaties;
    }

    /** Ticks; 0 = a pose that lasts (houding); -1 = the kind's file does not hold that name (never throws for a kind of ours). */
    public static int duur(GuhNpcEntity.Kind kind, String animatie) {
        GeestKinds r = rij(kind);
        if (r == null) {
            return -1;
        }
        int i = r.animaties.indexOf(animatie);
        return i < 0 ? -1 : r.duren[i];
    }
}
